// 彩云天气第 7 套锁屏图标（白色圆润云朵 + 太阳），原始 PNG 嵌成 base64，锁屏里直接解码用。
// 来源：cnb.cool/enjoyeetime/MyScriptable 的 彩云天气/img/icon/weather7/，缩到最长边 90px。
// 图标名就是彩云的 skycon；下面把 Scripting 这边的 SF Symbol 名字映射过去。

declare const UIImage: { fromBase64String(value: string): { width: number; height: number } | null } | undefined;

const DATA: Record<string, string> = {
  CLEAR_DAY: "",
  CLEAR_NIGHT: "",
  PARTLY_CLOUDY_DAY: "",
  PARTLY_CLOUDY_NIGHT: "",
  CLOUDY: "",
  LIGHT_HAZE: "",
  MODERATE_HAZE: "",
  HEAVY_HAZE: "",
  LIGHT_RAIN: "",
  MODERATE_RAIN: "",
  HEAVY_RAIN: "",
  STORM_RAIN: "",
  FOG: "",
  LIGHT_SNOW: "",
  MODERATE_SNOW: "",
  HEAVY_SNOW: "",
  STORM_SNOW: "",
  DUST: "",
  SAND: "",
  WIND: "",
};

const BY_SYMBOL: Record<string, string> = {
  "sun.max.fill": "CLEAR_DAY",
  "moon.stars.fill": "CLEAR_NIGHT",
  "moon.fill": "CLEAR_NIGHT",
  "cloud.sun.fill": "PARTLY_CLOUDY_DAY",
  "cloud.moon.fill": "PARTLY_CLOUDY_NIGHT",
  "cloud.fill": "CLOUDY",
  "cloud.fog.fill": "FOG",
  "smoke.fill": "HEAVY_HAZE",
  "sun.haze.fill": "LIGHT_HAZE",
  "moon.haze.fill": "LIGHT_HAZE",
  "cloud.drizzle.fill": "LIGHT_RAIN",
  "cloud.sun.rain.fill": "LIGHT_RAIN",
  "cloud.moon.rain.fill": "LIGHT_RAIN",
  "cloud.rain.fill": "MODERATE_RAIN",
  "cloud.heavyrain.fill": "HEAVY_RAIN",
  "cloud.bolt.rain.fill": "STORM_RAIN",
  "cloud.hail.fill": "STORM_RAIN",
  "cloud.sleet.fill": "LIGHT_SNOW",
  "cloud.snow.fill": "MODERATE_SNOW",
  "wind.snow": "STORM_SNOW",
  "sun.dust.fill": "DUST",
  "wind": "WIND",
  "sunrise.fill": "CLEAR_DAY",
  "sunset.fill": "CLEAR_DAY",
};

// 锁屏辅助图标（设计稿素材包里的白色透明 PNG）：温度计、升降箭头、风线、叶片、水滴、日出日落、空气、紫外线太阳。
const AUX: Record<string, string> = {
  thermometer: "",
  arrow_down: "",
  arrow_up: "",
  breeze: "",
  leaf: "",
  probability_drop: "",
  sunrise: "",
  sunset: "",
  air_quality: "",
  uv_sun: "",
};

const AUX_CACHE = new Map<string, { width: number; height: number } | null>();

/** 取一张锁屏辅助图；名字见 AUX 的键。取不到返回 null，调用方退回 SF Symbol。 */
export function lockAuxImage(name: string): { width: number; height: number } | null {
  if (AUX_CACHE.has(name)) return AUX_CACHE.get(name) ?? null;
  let image: { width: number; height: number } | null = null;
  try {
    image = typeof UIImage !== "undefined" ? UIImage.fromBase64String(AUX[name]) : null;
  } catch {
    image = null;
  }
  AUX_CACHE.set(name, image);
  return image;
}

const CACHE = new Map<string, { width: number; height: number } | null>();

/** 按 SF Symbol 名字取彩云图标；取不到（或当前环境没有 UIImage）返回 null，调用方退回 SF Symbol。 */
export function lockWeatherImage(symbol: string): { width: number; height: number } | null {
  const name = BY_SYMBOL[symbol] ?? "CLOUDY";
  if (CACHE.has(name)) return CACHE.get(name) ?? null;
  let image: { width: number; height: number } | null = null;
  try {
    image = typeof UIImage !== "undefined" ? UIImage.fromBase64String(DATA[name]) : null;
  } catch {
    image = null;
  }
  CACHE.set(name, image);
  return image;
}